      "text": "यहाँ का state बोला जाता है घाटकोपर।"
    },
    {
      "i": 31,
      "speaker": "bot",
      "text": "शायद आपने area का नाम बताया है।"
    },
    {
      "i": 32,
      "speaker": "bot",
      "text": "कृपया city और state का नाम बता दीजिए जैसे Mumbai Maharashtra।"
    },
    {
      "i": 33,
      "speaker": "caller",
      "text": "हाँ तो Mumbai Maharashtra ये है ना ये state।"
    },
    {
      "i": 34,
      "speaker": "bot",
      "text": "धन्यवाद।"
    },
    {
      "i": 35,
      "speaker": "bot",
      "text": "तो आप Mumbai Maharashtra से बोल रहे हैं ना?"
    },
    {
      "i": 36,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 37,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 38,
      "speaker": "bot",
      "text": "अब अपना नाम भी confirm कर दें आप राजू जी बोल रहे हैं ना?"
    },
    {
      "i": 39,
      "speaker": "caller",
      "text": "हाँ जी।"
    },
    {
      "i": 40,
      "speaker": "bot",
      "text": "ठीक है मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 41,
      "speaker": "caller",
      "text": "हाँ ये काम अच्छा है पसंद आएगा तो कह देंगे नहीं होगा तो भी आपको बता देंगे।"
    },
    {
      "i": 42,
      "speaker": "bot",
      "text": "हाँ।"
    }
  ]
}
